import { CarData, Driver, Lap } from '../types';

export interface DeltaPoint {
  distance: number;
  [key: string]: number | null;
}

interface ProcessedDeltaLap {
  traceId: string;
  driver: Driver;
  lap: Lap;
  points: {
    tRel: number;
    dist: number;
  }[];
  totalDist: number;
  actualDuration: number;
}

/**
 * Robust Linear Interpolation for finding Time at a specific Distance.
 */
const interpolateTimeAtDistance = (targetDist: number, points: { tRel: number; dist: number }[]): number | null => {
  if (points.length < 2) return null;
  if (targetDist < points[0].dist || targetDist > points[points.length - 1].dist) return null;

  // Binary search for the bounding segment
  let low = 0;
  let high = points.length - 1;
  while (low <= high) {
    const mid = (low + high) >>> 1;
    if (points[mid].dist < targetDist) low = mid + 1;
    else if (points[mid].dist > targetDist) high = mid - 1;
    else return points[mid].tRel;
  }

  const i = low;
  const p0 = points[i - 1];
  const p1 = points[i];

  if (!p0 || !p1) return null;
  const distDiff = p1.dist - p0.dist;
  if (distDiff === 0) return p0.tRel;

  const fraction = (targetDist - p0.dist) / distDiff;
  return p0.tRel + fraction * (p1.tRel - p0.tRel);
};

/**
 * Processes a single lap's car data into a time-distance profile.
 */
const processLapForDelta = (
  rawCarData: CarData[],
  lapStartStr: string,
  lapDuration: number,
  traceId: string,
  driver: Driver,
  lap: Lap
): ProcessedDeltaLap | null => {
  if (!rawCarData || rawCarData.length < 10) return null;

  // A. Sort and Sanitize
  const sorted = [...rawCarData]
    .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
    .filter((v, i, a) => i === 0 || v.date !== a[i - 1].date);

  const lapStartEpoch = new Date(lapStartStr).getTime();

  // B. Construct Relative Time
  // Find first index where t >= 0
  let firstIdx = sorted.findIndex(d => new Date(d.date).getTime() >= lapStartEpoch);
  if (firstIdx === -1) firstIdx = 0;

  const baseTime = new Date(sorted[firstIdx].date).getTime();

  // C. Integration & Filtering
  const integratedPoints = [];
  let cumulativeDist = 0;

  for (let i = 0; i < sorted.length; i++) {
    const d = sorted[i];
    const tRel = (new Date(d.date).getTime() - baseTime) / 1000;

    if (i > 0) {
      const prev = sorted[i - 1];
      const dt = (new Date(d.date).getTime() - new Date(prev.date).getTime()) / 1000;

      // dt clamp for stability
      const clampedDt = Math.min(Math.max(dt, 0), 0.5);

      const v1 = d.speed / 3.6;
      const v0 = prev.speed / 3.6;
      const distDelta = 0.5 * (v1 + v0) * clampedDt;

      // Physics filter
      if (distDelta >= 0 && distDelta < 120) {
        cumulativeDist += distDelta;
      }
    }

    // Window filter: slightly wider than duration for interpolation padding
    const durationLimit = lapDuration > 0 ? lapDuration : 140;
    if (tRel >= -1.0 && tRel <= durationLimit + 2.0) {
      integratedPoints.push({ tRel, dist: cumulativeDist });
    }
  }

  // D. Monotonicity Enforcement
  const cleanPoints: { tRel: number; dist: number }[] = [];
  let lastT = -Infinity;
  let lastD = -Infinity;

  for (const p of integratedPoints) {
    // Strictly increasing time, non-decreasing distance
    if (p.tRel > lastT + 0.0001) {
      // To ensure t(dist) is invertible, distance should be increasing.
      // If speed is 0, distance stays same. We'll add a tiny epsilon if needed or just skip.
      // We'll enforce a tiny increment for distance if time moved but distance didn't (e.g. stopped).
      const effectiveDist = Math.max(p.dist, lastD + 0.0001);

      cleanPoints.push({ tRel: p.tRel, dist: effectiveDist });
      lastT = p.tRel;
      lastD = effectiveDist;
    }
  }

  if (cleanPoints.length < 50) return null;

  return {
    traceId,
    driver,
    lap,
    points: cleanPoints,
    totalDist: cleanPoints[cleanPoints.length - 1].dist,
    actualDuration: cleanPoints[cleanPoints.length - 1].tRel
  };
};

/**
 * Builds the master delta series comparing all laps to the fastest one.
 */
export const buildDeltaSeries = (
  inputs: { traceId: string; lapStartDate: string; lapDuration: number; data: CarData[]; driver: Driver; lap: Lap }[]
): { deltaData: DeltaPoint[]; referenceTraceId: string | null } => {
  // 1. Process all laps
  const processedLaps: ProcessedDeltaLap[] = [];
  for (const input of inputs) {
    const res = processLapForDelta(input.data, input.lapStartDate, input.lapDuration, input.traceId, input.driver, input.lap);
    if (res) processedLaps.push(res);
  }

  if (processedLaps.length === 0) return { deltaData: [], referenceTraceId: null };

  // 2. Identify Reference (Fastest duration)
  const refLap = processedLaps.reduce((prev, curr) => {
    const prevDur = prev.lap.lap_duration > 0 ? prev.lap.lap_duration : prev.actualDuration;
    const currDur = curr.lap.lap_duration > 0 ? curr.lap.lap_duration : curr.actualDuration;
    return currDur < prevDur ? curr : prev;
  });

  const referenceTraceId = refLap.traceId;

  // 3. Create Master Grid (Distance-based)
  const STEP_METERS = 2;
  const maxRefDist = refLap.totalDist;
  const grid: number[] = [];
  for (let d = 0; d <= maxRefDist; d += STEP_METERS) {
    grid.push(d);
  }

  // 4. Calculate Deltas
  const deltaData: DeltaPoint[] = grid.map(dist => {
    const row: DeltaPoint = { distance: dist };

    const tRef = interpolateTimeAtDistance(dist, refLap.points);
    if (tRef === null) {
        // Lap hasn't started or ended at this distance on ref
        return row;
    }

    processedLaps.forEach(l => {
      const tComp = interpolateTimeAtDistance(dist, l.points);
      if (tComp !== null) {
        // Delta = Comp - Ref
        // Positive = Comp is slower (took more time to reach same distance)
        row[`delta_${l.traceId}`] = tComp - tRef;
      } else {
        row[`delta_${l.traceId}`] = null;
      }
    });

    return row;
  });

  return { deltaData, referenceTraceId };
};

import React, { useState, useMemo, useRef, useLayoutEffect } from 'react';
import ReactApexChart from 'react-apexcharts';
import { ApexOptions } from 'apexcharts';
import { motion, AnimatePresence } from 'framer-motion';
import { DeltaPoint, StagedLap } from '../types';
import { generateSeriesColors } from '../utils/teamColors';

interface TelemetryDeltaChartProps {
  data: any[]; // DeltaPoint[]
  stagedLaps: StagedLap[];
  referenceTraceId: string | null;
}

const ResponsiveApexChart: React.FC<{
    options: ApexOptions;
    series: ApexOptions['series'];
    type: "line" | "area" | "bar";
    className?: string;
}> = ({ options, series, type, className }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [shouldRender, setShouldRender] = useState(false);

    useLayoutEffect(() => {
        if (!containerRef.current) return;
        const resizeObserver = new ResizeObserver((entries) => {
            if (!Array.isArray(entries) || !entries.length) return;
            const { width, height } = entries[0].contentRect;
            if (width > 0 && height > 0) {
                requestAnimationFrame(() => setShouldRender(true));
            }
        });
        resizeObserver.observe(containerRef.current);
        return () => resizeObserver.disconnect();
    }, []);

    return (
        <div ref={containerRef} className={`w-full h-full relative min-h-[100px] ${className || ''}`}>
            {shouldRender ? (
                <ReactApexChart options={options} series={series} type={type} height="100%" width="100%" />
            ) : (
                <div className="absolute inset-0 flex items-center justify-center opacity-30">
                     <div className="w-6 h-6 border-2 border-f1-red border-t-transparent rounded-full animate-spin"></div>
                </div>
            )}
        </div>
    );
};

const TelemetryDeltaChart: React.FC<TelemetryDeltaChartProps> = ({
  data,
  stagedLaps,
  referenceTraceId,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [hiddenIndices, setHiddenIndices] = useState<Set<number>>(new Set());

  const { series, chartColors, allColors } = useMemo(() => {
    const activeSeries: any[] = [];
    const activeColors: string[] = [];
    const baseColors = generateSeriesColors(stagedLaps.map(s => ({ team_name: s.driver.team_name })));

    stagedLaps.forEach((sl, index) => {
      if (hiddenIndices.has(index)) return;

      const traceId = `${sl.driver.name_acronym}_L${sl.lap.lap_number}`;
      const key = `delta_${traceId}`;

      const seriesData = data
        .filter(row => row[key] !== undefined && row[key] !== null)
        .map(row => [row.distance, row[key]]);

      if (seriesData.length > 0) {
        activeSeries.push({
          name: `${sl.driver.name_acronym} (L${sl.lap.lap_number})`,
          data: seriesData
        });
        activeColors.push(baseColors[index]);
      }
    });

    return { series: activeSeries, chartColors: activeColors, allColors: baseColors };
  }, [data, stagedLaps, hiddenIndices]);

  const options: ApexOptions = useMemo(() => ({
    chart: {
      type: 'line',
      animations: { enabled: false },
      background: 'transparent',
      fontFamily: 'JetBrains Mono, monospace',
      toolbar: { show: isExpanded },
      zoom: { enabled: isExpanded, type: 'x', autoScaleYaxis: true },
    },
    theme: { mode: 'dark' },
    colors: chartColors,
    stroke: { curve: 'smooth', width: 2.5 },
    grid: {
      borderColor: '#334155',
      strokeDashArray: 4,
      xaxis: { lines: { show: false } },
      yaxis: { lines: { show: true } },
    },
    annotations: {
      yaxis: [{
        y: 0,
        borderColor: '#94a3b8',
        label: {
          text: 'REF',
          style: { color: '#fff', background: '#FF1E00', fontSize: '9px' }
        }
      }]
    },
    xaxis: {
      type: 'numeric',
      labels: {
        style: { colors: '#94a3b8', fontSize: '10px' },
        formatter: (val) => `${Math.round(Number(val))}m`
      }
    },
    yaxis: {
      labels: {
        style: { colors: '#94a3b8', fontSize: '10px' },
        formatter: (val) => {
          const v = Number(val);
          return v === 0 ? "0.000" : (v > 0 ? `+${v.toFixed(3)}s` : `${v.toFixed(3)}s`);
        }
      },
      title: { text: 'Time Delta (s)', style: { color: '#64748b', fontSize: '10px', fontWeight: 600 } }
    },
    legend: { show: false },
    tooltip: {
      theme: 'dark',
      x: { formatter: (val) => `Distance: ${Math.round(Number(val))}m` },
      y: {
        formatter: (val) => {
          const v = Number(val);
          return v === 0 ? "Benchmark" : (v > 0 ? `+${v.toFixed(3)}s slower` : `${v.toFixed(3)}s faster`);
        }
      }
    }
  }), [chartColors, isExpanded]);

  const toggleVisibility = (index: number) => {
    const next = new Set(hiddenIndices);
    if (next.has(index)) next.delete(index);
    else next.add(index);
    setHiddenIndices(next);
  };

  if (!data || data.length === 0) return null;

  const refLap = stagedLaps.find(sl => `delta_${sl.driver.name_acronym}_L${sl.lap.lap_number}` === `delta_${referenceTraceId}`);

  return (
    <>
      <div className="relative w-full h-[360px] bg-[#121218] border border-f1-red/20 rounded-lg p-5 flex flex-col mb-8 shadow-2xl group/delta overflow-hidden">
        {/* Glow effect */}
        <div className="absolute -top-24 -right-24 w-48 h-48 bg-f1-red/5 blur-[100px] pointer-events-none"></div>

        <div className="flex justify-between items-center mb-4 shrink-0 h-8 relative z-10">
          <div className="flex items-center gap-3">
            <div className="p-1.5 bg-f1-red/10 rounded-sm">
                <svg className="w-4 h-4 text-f1-red" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
                </svg>
            </div>
            <div>
                <h3 className="text-sm font-bold uppercase tracking-tighter text-white">Time Delta Analysis</h3>
                <p className="text-[9px] text-f1-muted uppercase tracking-widest">Relative to {refLap?.driver.name_acronym || 'Fastest Lap'}</p>
            </div>
          </div>

          <div className="flex flex-wrap gap-2">
            {stagedLaps.map((sl, index) => {
              const isHidden = hiddenIndices.has(index);
              const color = allColors[index];
              const isRef = referenceTraceId === `${sl.driver.name_acronym}_L${sl.lap.lap_number}`;
              return (
                <button 
                  key={sl.id} 
                  onClick={() => toggleVisibility(index)}
                  className={`flex items-center gap-2 px-2 py-1 rounded border border-transparent text-[10px] font-bold transition-all duration-200 ${isHidden ? 'opacity-30 bg-transparent line-through' : 'bg-white/5 hover:bg-white/10'}`}
                >
                  <span className={`w-2 h-2 rounded-full ${isRef ? 'ring-2 ring-f1-red ring-offset-1 ring-offset-transparent' : ''}`} style={{ backgroundColor: color }}></span>
                  <span className="uppercase text-f1-text">{sl.driver.name_acronym}</span>
                </button>
              );
            })}
            <button 
                onClick={() => setIsExpanded(true)}
                className="ml-2 p-1.5 rounded bg-white/5 hover:bg-f1-red text-f1-muted hover:text-white transition-all"
            >
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" /></svg>
            </button>
          </div>
        </div>

        <div className="flex-1 w-full min-h-0 relative z-10">
          <ResponsiveApexChart options={options} series={series} type="line" />
        </div>
      </div>

      <AnimatePresence>
        {isExpanded && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setIsExpanded(false)} className="absolute inset-0 bg-black/95 backdrop-blur-md" />
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }} className="relative w-full max-w-7xl h-[85vh] bg-[#0F1014] border border-white/5 rounded-2xl p-8 shadow-2xl flex flex-col overflow-hidden">
               <div className="flex justify-between items-center mb-8 shrink-0">
                  <div>
                    <h3 className="text-2xl font-bold uppercase tracking-tighter text-white">Full Lap Delta Map</h3>
                    <p className="text-xs text-f1-muted mt-1 uppercase tracking-widest">Precision analysis of time gain/loss over distance</p>
                  </div>
                  <button onClick={() => setIsExpanded(false)} className="p-3 bg-white/5 hover:bg-f1-red text-white rounded-full transition-all">
                    <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                  </button>
               </div>
               <div className="flex-1 w-full min-h-0 bg-black/40 rounded-xl border border-white/5 p-4">
                  <ResponsiveApexChart options={options} series={series} type="line" />
               </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </>
  );
};

export default React.memo(TelemetryDeltaChart);

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { getSessions, getDrivers, getLaps, getCarTelemetry, getLatestSession } from './services/openf1Service';
import { analyzeTelemetry } from './services/geminiService';
import { Session, Driver, Lap, AIAnalysisResult, StagedLap } from './types';
import SessionSelector from './components/SessionSelector';
import TelemetrySingleChart from './components/TelemetrySingleChart';
import TelemetryDeltaChart from './components/TelemetryDeltaChart';
import AIAnalysis from './components/AIAnalysis';
import LapHistoryChart from './components/LapHistoryChart';
import DriverSelector from './components/DriverSelector';
import { processTelemetryData, formatLapTime } from './utils/telemetryUtils';
import { buildDeltaSeries } from './utils/deltaUtils';
import { getTeamColors } from './utils/teamColors';
import { FALLBACK_COLOR } from './utils/chartUtils';

// --- CONSTANTS ---
const CURRENT_YEAR = new Date().getFullYear();
const START_YEAR = 2023;
const AVAILABLE_YEARS = Array.from({ length: CURRENT_YEAR - START_YEAR + 1 }, (_, i) => CURRENT_YEAR - i);
const MAX_LAPS = 8;

export const App: React.FC = () => {
  // --- STATE ---
  const [selectedYear, setSelectedYear] = useState<number>(CURRENT_YEAR);
  const [sessions, setSessions] = useState<Session[]>([]);
  const [selectedSession, setSelectedSession] = useState<Session | null>(null);

  const [allDrivers, setAllDrivers] = useState<Driver[]>([]);
  const [selectedDrivers, setSelectedDrivers] = useState<Driver[]>([]);

  const pendingRandomCountRef = useRef<number | null>(null);
  const [isRandomizing, setIsRandomizing] = useState(false);

  // Data Containers
  const [lapsData, setLapsData] = useState<Map<number, Lap[]>>(new Map());
  const [stagedLaps, setStagedLaps] = useState<StagedLap[]>([]);
  const [telemetryData, setTelemetryData] = useState<any[]>([]);
  const [deltaData, setDeltaData] = useState<any[]>([]);
  const [referenceTraceId, setReferenceTraceId] = useState<string | null>(null);

  // Loading States
  const [loadingLaps, setLoadingLaps] = useState(false);
  const [loadingTelemetry, setLoadingTelemetry] = useState(false);
  const [loadingSessions, setLoadingSessions] = useState(false);

  const [aiResult, setAiResult] = useState<AIAnalysisResult | null>(null);
  const [analyzing, setAnalyzing] = useState(false);

  // --- INITIALIZATION ---
  useEffect(() => {
    let mounted = true;
    const init = async () => {
        setLoadingSessions(true);
        try {
            const latest = await getLatestSession();
            if(!mounted) return;

            if(latest) {
                setSelectedYear(latest.year);
                const allSessions = await getSessions(latest.year);
                if(mounted) {
                    setSessions(allSessions);
                    setSelectedSession(latest);
                }
            } else {
                const allSessions = await getSessions(selectedYear);
                if(mounted) setSessions(allSessions);
            }
        } catch (e) {
            console.error("Init Error", e);
        } finally {
            if(mounted) setLoadingSessions(false);
        }
    };
    init();
    return () => { mounted = false; };
  }, []);

  // --- DRIVER LOADING ---
  useEffect(() => {
    if (!selectedSession) return;
    let mounted = true;
    const loadDrivers = async () => {
        try {
            const d = await getDrivers(selectedSession.session_key);
            if (mounted) {
                const unique = d.filter((v, i, a) => a.findIndex(t => (t.driver_number === v.driver_number)) === i);
                setAllDrivers(unique);

                if (pendingRandomCountRef.current !== null) {
                    const count = pendingRandomCountRef.current;
                    const shuffled = [...unique].sort(() => 0.5 - Math.random());
                    setSelectedDrivers(shuffled.slice(0, count));
                    pendingRandomCountRef.current = null;
                } else {
                    setSelectedDrivers([]);
                }
                setLapsData(new Map());
                setStagedLaps([]);
                setTelemetryData([]);
                setDeltaData([]);
            }
        } catch (e) { console.error(e); }
    };
    loadDrivers();
    return () => { mounted = false; };
  }, [selectedSession]);

  // --- HANDLERS ---
  const handleYearChange = async (year: number) => {
      if(year === selectedYear) return;
      setSelectedYear(year);
      setLoadingSessions(true);
      setSelectedSession(null);
      setSessions([]);

      try {
          const newSessions = await getSessions(year);
          setSessions(newSessions);
          if (newSessions.length > 0) setSelectedSession(newSessions[0]);
      } catch (e) { console.error(e); } 
      finally { setLoadingSessions(false); }
  };

  const handleRefreshSessions = async () => {
      setLoadingSessions(true);
      try {
          const freshSessions = await getSessions(selectedYear);
          setSessions(freshSessions);
          if (selectedSession) {
              const stillExists = freshSessions.find(s => s.session_key === selectedSession.session_key);
              if (stillExists) setSelectedSession(stillExists);
          } else if (freshSessions.length > 0) {
               setSelectedSession(freshSessions[0]);
          }
      } catch (e) { console.error(e); } 
      finally { setLoadingSessions(false); }
  };

  const handleToggleDriver = (driver: Driver) => {
      const exists = selectedDrivers.find(d => d.driver_number === driver.driver_number);
      if (exists) {
          setSelectedDrivers(prev => prev.filter(d => d.driver_number !== driver.driver_number));
          setLapsData(prev => {
              const next = new Map(prev);
              next.delete(driver.driver_number);
              return next;
          });
          setStagedLaps(prev => prev.filter(sl => sl.driver.driver_number !== driver.driver_number));
      } else {
          if (selectedDrivers.length < 6) setSelectedDrivers(prev => [...prev, driver]);
      }
  };

  const loadLapHistory = useCallback(async () => {
      if (!selectedSession || selectedDrivers.length === 0) return;
      setLoadingLaps(true);
      const newLapsMap = new Map<number, Lap[]>();
      try {
          await Promise.all(selectedDrivers.map(async (d) => {
              const laps = await getLaps(selectedSession.session_key, d.driver_number);
              const validLaps = laps.filter(l => l.lap_duration > 0);
              newLapsMap.set(d.driver_number, validLaps);
          }));
          setLapsData(newLapsMap);
          setStagedLaps([]); 
      } catch (e) { console.error(e); } 
      finally { setLoadingLaps(false); }
  }, [selectedSession, selectedDrivers]);

  useEffect(() => {
      if (isRandomizing && selectedDrivers.length > 0) {
          loadLapHistory();
          setIsRandomizing(false);
      }
  }, [selectedDrivers, isRandomizing, loadLapHistory]);

  const syncTelemetry = async () => {
      if (!selectedSession || stagedLaps.length === 0) return;
      setLoadingTelemetry(true);
      setAiResult(null);

      try {
          const inputs = await Promise.all(stagedLaps.map(async (sl) => {
              const { driver, lap } = sl;
              const buffer = 3.0; 
              const data = await getCarTelemetry(
                  selectedSession.session_key, 
                  driver.driver_number, 
                  new Date(new Date(lap.date_start).getTime() - 2000).toISOString(), 
                  new Date(new Date(lap.date_start).getTime() + (lap.lap_duration + buffer) * 1000).toISOString()
              );
              const traceId = `${driver.name_acronym}_L${lap.lap_number}`;
              return { driver, data, lapStartDate: lap.date_start, lapDuration: lap.lap_duration, traceId, lap };
          }));

          const validInputs = inputs.filter(i => i.data && i.data.length > 0);
          if (validInputs.length > 0) {
              // Standard Telemetry
              const processed = processTelemetryData(validInputs);
              setTelemetryData(processed);

              // New Delta Pipeline
              const { deltaData, referenceTraceId } = buildDeltaSeries(validInputs);
              setDeltaData(deltaData);
              setReferenceTraceId(referenceTraceId);
          }
      } catch(e) { console.error(e); } 
      finally { setLoadingTelemetry(false); }
  };

  const handleRandomize = useCallback(async () => {
      setLoadingSessions(true);
      setSelectedDrivers([]); 
      setLapsData(new Map());
      setStagedLaps([]);
      setTelemetryData([]);
      setDeltaData([]);
      setIsRandomizing(true);
      try {
          const randomYear = AVAILABLE_YEARS[Math.floor(Math.random() * AVAILABLE_YEARS.length)];
          const allSessions = await getSessions(randomYear);
          const qualifyingSessions = allSessions.filter(s => s.session_name === 'Qualifying');

          if (qualifyingSessions.length === 0) {
             setLoadingSessions(false); setIsRandomizing(false); return;
          }

          const randomSession = qualifyingSessions[Math.floor(Math.random() * qualifyingSessions.length)];
          const count = Math.floor(Math.random() * 3) + 2; 

          pendingRandomCountRef.current = count;
          setSelectedYear(randomYear);
          setSessions(allSessions);
          setSelectedSession(randomSession);

      } catch (e) {
          console.error(e); setIsRandomizing(false);
      } finally { setLoadingSessions(false); }
  }, []);

